# import ehrql libraries
from ehrql import create_dataset, days, show, case, when
from ehrql.tables.tpp import patients, practice_registrations, ons_deaths
from ehrql.tables.raw.tpp import repeat_medications, medications
from datetime import date

# get codelists
import codelists

# create dataset from dummy tables generated by ehrQL
dataset = create_dataset()

# define start of period of interest
index_date = "2025-01-01"

# require registration to exist 
has_registration = practice_registrations.for_patient_on(
    index_date
).exists_for_patient()

# require patient to be alive/dead: use ONS record if present, otherwise use GP record
death_date = ons_deaths.date.when_null_then(patients.date_of_death)
was_alive = death_date.is_after(index_date) | death_date.is_null()
correct_age = patients.age_on(index_date) <= 110

# filter to patients with at least one medication record in relevant period
meds_exist = (
    medications.where(medications.date.is_on_or_after(index_date))
    .exists_for_patient()
)

# define population
dataset.define_population(
    has_registration & 
    was_alive &
    correct_age &
    meds_exist
)

# configure the dummy data
dataset.configure_dummy_data(
    population_size = 50
)

# remove private prescriptions
medications = medications.where(medications.medication_status != 6)
repeat_medications = repeat_medications.where(repeat_medications.medication_status != 6)

# get number of repeat prescriptions per patient which are active 
dataset.active_repeats = (
    repeat_medications.where(repeat_medications.end_date.is_after(index_date))
    .repeat_medication_id.count_distinct_for_patient()
)

# get first row for each patient
medications_rows = (
    medications
    .where(medications.date.is_on_or_after(index_date))
    .sort_by(medications.date)
    .first_for_patient()
)
repeat_rows = (
    repeat_medications
    .where(repeat_medications.date.is_on_or_after(index_date))
    .sort_by(repeat_medications.date)
    .first_for_patient()
)

# get date distributions
dataset.meds_sample_date = (
    medications_rows.date
)
dataset.repeats_sample_date = (
    repeat_rows.date
)
dataset.repeats_sample_start_date = (
    repeat_rows.start_date
)
dataset.repeats_sample_end_date = (
    repeat_rows.end_date
)

# get number of rows for meds table
dataset.meds_row_no = (
    medications.where(medications.date.is_on_or_after(index_date))
    .count_for_patient()
)

# get number of unique repeat ids
dataset.meds_rep_id_no = (
    medications.where(medications.date.is_on_or_after(index_date))
    .where(medications.repeat_medication_id != -1)
    .repeat_medication_id.count_distinct_for_patient()
)

# get number of unique consultation ids
dataset.meds_consult_id_no = (
    medications.where(medications.date.is_on_or_after(index_date))
    .consultation_id.count_distinct_for_patient() 
)

# get number of rows for repeat meds table
dataset.repeats_row_no = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .count_for_patient()
)

# get number of unique repeat ids
dataset.repeats_rep_id_no = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .repeat_medication_id.count_distinct_for_patient()
)

# get number of unique consultation ids
dataset.repeats_consult_id_no = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .consultation_id.count_distinct_for_patient()
)

# get whether the number of unique ids differs per patient
dataset.rep_ids_differ = dataset.meds_rep_id_no != dataset.repeats_rep_id_no

# get information on missing data
dataset.medications_missing_rep_id = (
    medications.where(medications.date.is_on_or_after(index_date))
    .where(medications.repeat_medication_id == 0)
    .count_for_patient()
)
dataset.rep_missing_date = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.date.is_after(date.today()))
    .count_for_patient()
)
dataset.rep_missing_start_date = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .where(~repeat_medications.start_date.is_between_but_not_on(index_date-days(1), "9999-12-31"))
    .count_for_patient()
)
dataset.rep_missing_end_date = (
    repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.end_date.is_after(date.today()))
    .count_for_patient()
)

# get number of occasions start_date and consultation date are same per patient
dataset.concordant_dates = (
    repeat_medications
    .where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.date == repeat_medications.start_date)
    .date
    .count_distinct_for_patient()
)

# get number of occasions start_date and consultation date are different per patient
dataset.discordant_dates = (
    repeat_medications
    .where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.date != repeat_medications.start_date)
    .date
    .count_distinct_for_patient()
)

# get number of occurrences of start_date before date and start_date after date
dataset.start_date_first = (
    repeat_medications
    .where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.start_date.is_after("1900-01-01"))
    .where(repeat_medications.date > repeat_medications.start_date)
    .count_for_patient()
)
dataset.start_date_second = (
    repeat_medications
    .where(repeat_medications.date.is_on_or_after(index_date))
    .where(repeat_medications.start_date.is_on_or_between(index_date, "9999-12-31"))
    .where(repeat_medications.date < repeat_medications.start_date)
    .count_for_patient()
)

# get information about medication type
# Count all medication status
# This will add 6 x 28 = 168 new columns
for status in range(29):
    count_med_status_query = (
        medications.where(medications.date.is_on_or_after(index_date))
        .where(medications.medication_status.is_in([status]))
        .count_for_patient()
    )
    dataset.add_column(f"medications_status_{status}", count_med_status_query)
    count_rep_med_status_query = (
        repeat_medications.where(repeat_medications.date.is_on_or_after(index_date))
        .where(repeat_medications.medication_status.is_in([status]))
        .count_for_patient()
    )
    dataset.add_column(f"repeats_status_{status}", count_rep_med_status_query)    

## check for repeat ids which match across tables
#dataset.has_matching_repeat_med = (
#    .where(medications.repeat_medication_id.is_in(repeat_medications.repeat_medication_id))
#    medications.where(medications.date.is_on_or_after(index_date))
#    .where(medications.dmd_code == repeat_medications.dmd_code)
#    .exists_for_patient()
#)
#show(dataset.has_matching_repeat_med)
dataset.has_matching_repeat_med = (case(
    when(medications_rows.repeat_medication_id == repeat_rows.repeat_medication_id)
    .then(True),
    otherwise = False)
)